99	pub fn create_web_search_tool(options: WebSearchToolOptions<'_>) -> Option<ToolSpec> {
100	    let external_web_access = match options.web_search_mode {
101	        Some(WebSearchMode::Cached) => Some(false),
102	        Some(WebSearchMode::Live) => Some(true),
103	        Some(WebSearchMode::Disabled) | None => None,
104	    }?;
105	
106	    let search_content_types = match options.web_search_tool_type {
107	        WebSearchToolType::Text => None,
108	        WebSearchToolType::TextAndImage => Some(
109	            WEB_SEARCH_TEXT_AND_IMAGE_CONTENT_TYPES
110	                .into_iter()
111	                .map(str::to_string)
112	                .collect(),
113	        ),
114	    };
115	
116	    Some(ToolSpec::WebSearch {
117	        external_web_access: Some(external_web_access),
118	        filters: options
119	            .web_search_config
120	            .and_then(|config| config.filters.clone().map(Into::into)),
121	        user_location: options
122	            .web_search_config
123	            .and_then(|config| config.user_location.clone().map(Into::into)),
124	        search_context_size: options
125	            .web_search_config
126	            .and_then(|config| config.search_context_size),
127	        search_content_types,
128	    })
129	}
